// half-open window [watermark − overlap, run_ts); computed ONCE — every later node references this item, never $now again
const P = $('Params').first().json; const wm = $input.first().json.watermark;
const runTs = new Date(P.run_ts); const start = wm ? new Date(wm) : new Date(runTs.getTime() - P.first_run_days * 86400000);
const qs = new Date(start.getTime() - P.overlap_minutes * 60000);
const iso = (d) => d.toISOString().replace('.000Z', 'Z');
return [{ json: { watermark_in: iso(start), query_start: iso(qs), query_end: iso(runTs), hs_start: iso(qs).replace('Z', '.000Z'), hs_end: iso(runTs).replace('Z', '.000Z') } }];

// NEW_DEALS_FULL · Code node "Shape + score" (runOnceForAllItems). GENERATED by workflows/src/build_workflow.py — do not edit here.
const C = {"version": "v1", "fitted": "2026-10-01", "weights": {"stage_prob": 2.0712, "proximity_2026": 1.2399, "missing_2026_field": -0.4136, "pipeline_conversion": 1.0918, "arr_points": 4.9843, "engagement": 1.3018, "recency": 0.0, "not_in_forecast": 1.562}, "bias": -6.4788, "threshold": 45.0, "conversion": {"12096408": {"won": 84, "total": 730}, "13772279": {"won": 51, "total": 303}}, "hardware_pipeline": "12096408", "max_contacted_notes": 223, "horizon_date": "2026-12-31", "horizon_decay_days": 730, "arr_tiers": {"PKI": [[20, 0.5], [50, 1], [null, 2]], "default": [[100, 0.5], [500, 1], [1000, 2], [null, 3]]}, "arr_tier_divisor": 3, "recency_days": [[90, 1.0], [180, 0.5]], "forecast_states": ["Forecast", "BIBA"]};
// shape_score.js — pure functions injected into the n8n Code node by build_workflow.py (no imports; `C` = constants object).
// Port of hot_score(), name_key() and shape() from cloud_function_new_deals/main.py. Verified by tests/test_n8n_code.py
// against the Python implementation on identical inputs.
const num = (v) => { if (v === null || v === undefined || v === '') return 0; const f = Number(v); return Number.isFinite(f) ? f : 0; };
const daysBetween = (later, earlier) => Math.trunc((later - earlier) / 86400000);
const CRMAX = Math.max(...Object.values(C.conversion).map((c) => c.won / c.total));

function hotScore(p, now) {
  const cr = C.conversion[p.pipeline];
  if (!cr) return [null, null];
  const arr = num(p.asp_in_usd_q2_2022_calculation) || num(p.tpm__k_y) || num(p.services_value_2026);
  const tiers = p.product_hierarchy === 'PKI' ? C.arr_tiers.PKI : C.arr_tiers.default;
  let pts = tiers[tiers.length - 1][1];
  for (const [limit, value] of tiers) {
    if (limit === null) { pts = value; break; }
    if (limit === tiers[0][0] ? arr < limit : arr <= limit) { pts = value; break; }
  }
  let prox = 0;
  if (p.closedate) { const d = new Date(p.closedate); prox = d.getUTCFullYear() <= 2026 ? 1 : Math.max(0, 1 - daysBetween(d, new Date(C.horizon_date + 'T00:00:00Z')) / C.horizon_decay_days); }
  const hw = p.pipeline === C.hardware_pipeline;
  const missing = (hw ? !num(p.calculation___pipeline_2026__k__) : !num(p.services_value_2026)) ? 1 : 0;
  let rec = 0;
  if (p.notes_last_updated) { const dd = daysBetween(now, new Date(p.notes_last_updated)); rec = dd <= C.recency_days[0][0] ? C.recency_days[0][1] : (dd <= C.recency_days[1][0] ? C.recency_days[1][1] : 0); }
  const f = { stage_prob: num(p.hs_deal_stage_probability), proximity_2026: prox, missing_2026_field: missing, pipeline_conversion: (cr.won / cr.total) / CRMAX,
    arr_points: pts / C.arr_tier_divisor, engagement: Math.log1p(num(p.num_contacted_notes)) / Math.log1p(C.max_contacted_notes), recency: rec,
    not_in_forecast: C.forecast_states.includes(p.revenue_state) ? 0 : 1 };
  const z = Object.keys(C.weights).reduce((a, k) => a + C.weights[k] * f[k], 0) + C.bias;
  const s = 100 / (1 + Math.exp(-z));
  return [Math.round(s * 10) / 10, s >= C.threshold];
}

function nameKey(p) {
  const base = (p.final_customer || '').trim() || (p.dealname || '').split(/[-/|(]/)[0];
  return base.toLowerCase().replace(/[^a-z0-9]/g, '').slice(0, 40);
}

function shapeRows(deals, others, entity, pl, st, owners, runTs, known, portal) {
  const batchKeys = {};
  for (const d of [...deals, ...others]) { const k = nameKey(d.properties || {}); (batchKeys[k] ??= []).push(String(d.id)); }
  const iso = runTs.toISOString().replace('.000Z', '+00:00');
  return deals.map((d) => {
    const p = d.properties || {}; const did = String(d.id); const k = nameKey(p);
    const dupBatch = (batchKeys[k] || []).filter((x) => x !== did);
    const dupKnown = (known[k] || []).filter((x) => x !== did && !dupBatch.includes(x));
    const [score, hot] = hotScore(p, runTs);
    const ownerId = p.hubspot_owner_id === undefined || p.hubspot_owner_id === null ? null : String(p.hubspot_owner_id);
    return { entity, deal_id: did, dealname: p.dealname ?? null, final_customer: p.final_customer ?? null, name_key: k,
      createdate: p.createdate ?? null, created_by_user_id: p.hs_created_by_user_id ?? null, source: p.hs_object_source_label ?? null,
      owner: ownerId === null ? null : (owners[ownerId] ?? ownerId), sales_region: p.sales_region ?? null,
      pipeline: pl[p.pipeline] ?? p.pipeline ?? null, pipeline_id: p.pipeline ?? null, stage: st[p.dealstage] ?? p.dealstage ?? null,
      probability_pct: Math.round(num(p.hs_deal_stage_probability) * 1000) / 10, amount: num(p.amount), currency: p.deal_currency_code ?? null,
      amount_kusd: num(p.amount_in_home_currency), closedate: (p.closedate || '').slice(0, 10) || null,
      arr_ky: num(p.asp_in_usd_q2_2022_calculation), product_family: p.product_hierarchy ?? null, product: p.prod___product_name_new_ ?? null,
      application: p.application ?? null, icalps_dealtype: p.icalps_dealtype ?? null, icalps_stage: p.icalps_stage ?? null,
      day1_hot_score: score, day1_hot_flag: hot,
      duplicate_suspect: dupBatch.length > 0 || dupKnown.length > 0, duplicate_of: [...dupBatch, ...dupKnown].join(', ') || null,
      deal_url: `https://app.hubspot.com/go-to/${portal}/0-3/${did}`, first_seen_run: iso, last_seen_run: iso };
  });
}
const MERGE_SQL = "MERGE __FQ__.new_deals` t USING (SELECT JSON_VALUE(r, '$.entity') AS entity, JSON_VALUE(r, '$.deal_id') AS deal_id, JSON_VALUE(r, '$.dealname') AS dealname, JSON_VALUE(r, '$.final_customer') AS final_customer, JSON_VALUE(r, '$.name_key') AS name_key, SAFE_CAST(JSON_VALUE(r, '$.createdate') AS TIMESTAMP) AS createdate, JSON_VALUE(r, '$.created_by_user_id') AS created_by_user_id, JSON_VALUE(r, '$.source') AS source, JSON_VALUE(r, '$.owner') AS owner, JSON_VALUE(r, '$.sales_region') AS sales_region, JSON_VALUE(r, '$.pipeline') AS pipeline, JSON_VALUE(r, '$.pipeline_id') AS pipeline_id, JSON_VALUE(r, '$.stage') AS stage, SAFE_CAST(JSON_VALUE(r, '$.probability_pct') AS FLOAT64) AS probability_pct, SAFE_CAST(JSON_VALUE(r, '$.amount') AS FLOAT64) AS amount, JSON_VALUE(r, '$.currency') AS currency, SAFE_CAST(JSON_VALUE(r, '$.amount_kusd') AS FLOAT64) AS amount_kusd, SAFE_CAST(JSON_VALUE(r, '$.closedate') AS DATE) AS closedate, SAFE_CAST(JSON_VALUE(r, '$.arr_ky') AS FLOAT64) AS arr_ky, JSON_VALUE(r, '$.product_family') AS product_family, JSON_VALUE(r, '$.product') AS product, JSON_VALUE(r, '$.application') AS application, JSON_VALUE(r, '$.icalps_dealtype') AS icalps_dealtype, JSON_VALUE(r, '$.icalps_stage') AS icalps_stage, SAFE_CAST(JSON_VALUE(r, '$.day1_hot_score') AS FLOAT64) AS day1_hot_score, SAFE_CAST(JSON_VALUE(r, '$.day1_hot_flag') AS BOOL) AS day1_hot_flag, SAFE_CAST(JSON_VALUE(r, '$.duplicate_suspect') AS BOOL) AS duplicate_suspect, JSON_VALUE(r, '$.duplicate_of') AS duplicate_of, JSON_VALUE(r, '$.deal_url') AS deal_url, SAFE_CAST(JSON_VALUE(r, '$.first_seen_run') AS TIMESTAMP) AS first_seen_run, SAFE_CAST(JSON_VALUE(r, '$.last_seen_run') AS TIMESTAMP) AS last_seen_run FROM UNNEST(JSON_QUERY_ARRAY(PARSE_JSON(__ROWS__))) r) s ON t.deal_id = s.deal_id WHEN MATCHED THEN UPDATE SET entity = s.entity, dealname = s.dealname, final_customer = s.final_customer, name_key = s.name_key, createdate = s.createdate, created_by_user_id = s.created_by_user_id, source = s.source, owner = s.owner, sales_region = s.sales_region, pipeline = s.pipeline, pipeline_id = s.pipeline_id, stage = s.stage, probability_pct = s.probability_pct, amount = s.amount, currency = s.currency, amount_kusd = s.amount_kusd, closedate = s.closedate, arr_ky = s.arr_ky, product_family = s.product_family, product = s.product, application = s.application, icalps_dealtype = s.icalps_dealtype, icalps_stage = s.icalps_stage, duplicate_suspect = s.duplicate_suspect, duplicate_of = s.duplicate_of, deal_url = s.deal_url, last_seen_run = s.last_seen_run WHEN NOT MATCHED THEN INSERT (entity, deal_id, dealname, final_customer, name_key, createdate, created_by_user_id, source, owner, sales_region, pipeline, pipeline_id, stage, probability_pct, amount, currency, amount_kusd, closedate, arr_ky, product_family, product, application, icalps_dealtype, icalps_stage, day1_hot_score, day1_hot_flag, duplicate_suspect, duplicate_of, deal_url, first_seen_run, last_seen_run) VALUES (s.entity, s.deal_id, s.dealname, s.final_customer, s.name_key, s.createdate, s.created_by_user_id, s.source, s.owner, s.sales_region, s.pipeline, s.pipeline_id, s.stage, s.probability_pct, s.amount, s.currency, s.amount_kusd, s.closedate, s.arr_ky, s.product_family, s.product, s.application, s.icalps_dealtype, s.icalps_stage, s.day1_hot_score, s.day1_hot_flag, s.duplicate_suspect, s.duplicate_of, s.deal_url, s.first_seen_run, s.last_seen_run)";
const HISTORY_SQL = "DELETE FROM __FQ__.new_deals_history` WHERE run_ts = TIMESTAMP '__RUN_TS__' AND entity = '__ENTITY__' AND orchestrator = 'n8n'; INSERT INTO __FQ__.new_deals_history` (run_ts, orchestrator, entity, deal_id, dealname, final_customer, name_key, createdate, created_by_user_id, source, owner, sales_region, pipeline, pipeline_id, stage, probability_pct, amount, currency, amount_kusd, closedate, arr_ky, product_family, product, application, icalps_dealtype, icalps_stage, day1_hot_score, day1_hot_flag, duplicate_suspect, duplicate_of, deal_url, first_seen_run, last_seen_run) SELECT TIMESTAMP '__RUN_TS__', 'n8n', entity, deal_id, dealname, final_customer, name_key, createdate, created_by_user_id, source, owner, sales_region, pipeline, pipeline_id, stage, probability_pct, amount, currency, amount_kusd, closedate, arr_ky, product_family, product, application, icalps_dealtype, icalps_stage, day1_hot_score, day1_hot_flag, duplicate_suspect, duplicate_of, deal_url, first_seen_run, last_seen_run FROM (SELECT JSON_VALUE(r, '$.entity') AS entity, JSON_VALUE(r, '$.deal_id') AS deal_id, JSON_VALUE(r, '$.dealname') AS dealname, JSON_VALUE(r, '$.final_customer') AS final_customer, JSON_VALUE(r, '$.name_key') AS name_key, SAFE_CAST(JSON_VALUE(r, '$.createdate') AS TIMESTAMP) AS createdate, JSON_VALUE(r, '$.created_by_user_id') AS created_by_user_id, JSON_VALUE(r, '$.source') AS source, JSON_VALUE(r, '$.owner') AS owner, JSON_VALUE(r, '$.sales_region') AS sales_region, JSON_VALUE(r, '$.pipeline') AS pipeline, JSON_VALUE(r, '$.pipeline_id') AS pipeline_id, JSON_VALUE(r, '$.stage') AS stage, SAFE_CAST(JSON_VALUE(r, '$.probability_pct') AS FLOAT64) AS probability_pct, SAFE_CAST(JSON_VALUE(r, '$.amount') AS FLOAT64) AS amount, JSON_VALUE(r, '$.currency') AS currency, SAFE_CAST(JSON_VALUE(r, '$.amount_kusd') AS FLOAT64) AS amount_kusd, SAFE_CAST(JSON_VALUE(r, '$.closedate') AS DATE) AS closedate, SAFE_CAST(JSON_VALUE(r, '$.arr_ky') AS FLOAT64) AS arr_ky, JSON_VALUE(r, '$.product_family') AS product_family, JSON_VALUE(r, '$.product') AS product, JSON_VALUE(r, '$.application') AS application, JSON_VALUE(r, '$.icalps_dealtype') AS icalps_dealtype, JSON_VALUE(r, '$.icalps_stage') AS icalps_stage, SAFE_CAST(JSON_VALUE(r, '$.day1_hot_score') AS FLOAT64) AS day1_hot_score, SAFE_CAST(JSON_VALUE(r, '$.day1_hot_flag') AS BOOL) AS day1_hot_flag, SAFE_CAST(JSON_VALUE(r, '$.duplicate_suspect') AS BOOL) AS duplicate_suspect, JSON_VALUE(r, '$.duplicate_of') AS duplicate_of, JSON_VALUE(r, '$.deal_url') AS deal_url, SAFE_CAST(JSON_VALUE(r, '$.first_seen_run') AS TIMESTAMP) AS first_seen_run, SAFE_CAST(JSON_VALUE(r, '$.last_seen_run') AS TIMESTAMP) AS last_seen_run FROM UNNEST(JSON_QUERY_ARRAY(PARSE_JSON(__ROWS__))) r)";
const WATERMARK_SQL = "MERGE __FQ__.report_state` t USING (SELECT '__RID__' AS report_id, TIMESTAMP '__TS__' AS watermark) s ON t.report_id = s.report_id WHEN MATCHED THEN UPDATE SET watermark = s.watermark, updated_at = CURRENT_TIMESTAMP(), lock_until = NULL WHEN NOT MATCHED THEN INSERT (report_id, watermark, updated_at) VALUES (s.report_id, s.watermark, CURRENT_TIMESTAMP())";
const RUNLOG_SQL = "INSERT INTO __FQ__.new_deals_runs` (run_ts, entity, mode, dry_run, orchestrator, watermark_in, query_start, query_end, row_count, rows_written, duplicate_suspects, day1_hot, status) VALUES (TIMESTAMP '__RUN_TS__', '__ENTITY__', 'window', __DRY__, 'n8n', TIMESTAMP '__WM__', TIMESTAMP '__QS__', TIMESTAMP '__QE__', __N__, IF(__DRY__, 0, __N__), __DUP__, __HOT__, 'OK')";
const ENTITIES = { SEALSQ: { pipelines: ['12096408', '13772279', '705868909', '934982230'], currency: 'USD (home)' }, ICALPS: { pipelines: ['766126206'], currency: 'EUR (stored)' } };
const P = $('Params').first().json;
const W = $('Window').first().json;
const runTs = new Date(P.run_ts);
const found = $('HubSpot search').all().flatMap((i) => i.json.results || []);
const pipelinesResp = $('Pipelines').first().json.results || [];
const pl = Object.fromEntries(pipelinesResp.map((p) => [p.id, p.label]));
const st = Object.fromEntries(pipelinesResp.flatMap((p) => (p.stages || []).map((s) => [s.id, s.label])));
const owners = Object.fromEntries($('Owners').all().flatMap((i) => i.json.results || []).map((o) => [String(o.id), `${o.firstName || ''} ${o.lastName || ''}`.trim() || o.email || '']));
const known = {};
for (const i of $('Recent names').all()) { const r = i.json || {}; if (r.name_key && r.deal_id) (known[r.name_key] ??= []).push(String(r.deal_id)); }
const scope = ENTITIES[P.entity].pipelines;
const deals = found.filter((d) => scope.includes((d.properties || {}).pipeline));
const ids = new Set(deals.map((d) => String(d.id)));
const others = found.filter((d) => !ids.has(String(d.id)));
const rows = shapeRows(deals, others, P.entity, pl, st, owners, runTs, known, P.portal_id);
rows.sort((a, b) => ((b.amount_kusd || 0) - (a.amount_kusd || 0)) || (a.deal_id < b.deal_id ? -1 : a.deal_id > b.deal_id ? 1 : 0));
const sqlStr = (s) => "'''" + String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'") + "'''";
const rowsLiteral = sqlStr(JSON.stringify(rows));
const fq = `\`${P.bq_project}.${P.bq_dataset}`;
const payload = { report_id: `NEW_DEALS_${P.entity}`, run_timestamp: P.run_ts, orchestrator: 'n8n', dry_run: P.dry_run === true,
  window: { mode: 'window', watermark_in: W.watermark_in, query_start: W.query_start, query_end: W.query_end },
  row_count: rows.length, rows_written: 0, duplicate_suspects: rows.filter((r) => r.duplicate_suspect).length,
  day1_hot: rows.filter((r) => r.day1_hot_flag).map((r) => r.deal_id), currency_note: ENTITIES[P.entity].currency, rows };
const merge_sql = rows.length ? MERGE_SQL.replaceAll('__FQ__', fq).replace('__ROWS__', () => rowsLiteral) : 'SELECT 1';   // function form: deal text may contain $& $$
const history_sql = rows.length ? HISTORY_SQL.replaceAll('__FQ__', fq).replace('__ROWS__', () => rowsLiteral).replaceAll('__RUN_TS__', P.run_ts).replaceAll('__ENTITY__', P.entity) : 'SELECT 1';
const watermark_sql = WATERMARK_SQL.replaceAll('__FQ__', fq).replaceAll('__RID__', `NEW_DEALS_${P.entity}`).replaceAll('__TS__', P.run_ts);
const runlog_sql = RUNLOG_SQL.replaceAll('__FQ__', fq).replaceAll('__RUN_TS__', P.run_ts).replaceAll('__ENTITY__', P.entity).replaceAll('__DRY__', String(P.dry_run === true))
  .replaceAll('__WM__', W.watermark_in).replaceAll('__QS__', W.query_start).replaceAll('__QE__', W.query_end)
  .replaceAll('__N__', String(rows.length)).replaceAll('__DUP__', String(payload.duplicate_suspects)).replaceAll('__HOT__', String(payload.day1_hot.length));
return [{ json: { ...payload, merge_sql, history_sql, watermark_sql, runlog_sql } }];

